from django.db import migrations, models


def mark_probably_living(apps, schema_editor):
    """Начальная разметка: нет смерти/погребения и родился меньше 110 лет назад — жив(а).

    Дальше галочка правится вручную на странице человека.
    """
    Person = apps.get_model("genealogy", "Person")
    Event = apps.get_model("genealogy", "Event")
    dead = set(Event.objects.filter(kind__in=("DEAT", "BURI"), person__isnull=False)
               .values_list("person_id", flat=True))
    since = (datetime.date.today().year - 110) * 10000
    born = Event.objects.filter(kind__in=("BIRT", "CHR"), person__isnull=False,
                                sort_key__gte=since, sort_key__lt=99999999)
    living = set(born.values_list("person_id", flat=True)) - dead
    Person.objects.filter(pk__in=living).update(is_living=True)


